        $this->assertNotEquals(true, $value->getBackchannelLogoutSessionRequiredOrDefault(TrustedClientBackchannelLogoutSessionRequiredVO::from($backchannelLogoutSessionRequiredOtherValue))->value());
        $frontchannelLogoutUriOneValue = 'one';
        $frontchannelLogoutUriOtherValue = 'other';
        $copy = $value->frontchannelLogoutUri($frontchannelLogoutUriOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getFrontchannelLogoutUri());
