        $this->assertNotEquals('other', $value->getFrontchannelLogoutUriOrDefault(TrustedClientFrontchannelLogoutUriVO::from($frontchannelLogoutUriOtherValue))->value());
        $value->unsetFrontchannelLogoutUri();
        $this->assertEquals('other', $value->getFrontchannelLogoutUriOrDefault(TrustedClientFrontchannelLogoutUriVO::from($frontchannelLogoutUriOtherValue))->value());
        $this->assertNotEquals('one', $value->getFrontchannelLogoutUriOrDefault(TrustedClientFrontchannelLogoutUriVO::from($frontchannelLogoutUriOtherValue))->value());
        $frontchannelLogoutSessionRequiredOneValue = true;
        $frontchannelLogoutSessionRequiredOtherValue = false;
        $copy = $value->frontchannelLogoutSessionRequired($frontchannelLogoutSessionRequiredOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isFrontchannelLogoutSessionRequired());
        $this->assertNotEquals(false, $value->isFrontchannelLogoutSessionRequired());
        $this->assertEquals(true, $value->getFrontchannelLogoutSessionRequiredOrDefault(TrustedClientFrontchannelLogoutSessionRequiredVO::from($frontchannelLogoutSessionRequiredOtherValue))->value());
        $this->assertNotEquals(false, $value->getFrontchannelLogoutSessionRequiredOrDefault(TrustedClientFrontchannelLogoutSessionRequiredVO::from($frontchannelLogoutSessionRequiredOtherValue))->value());
        $value->unsetFrontchannelLogoutSessionRequired();
        $this->assertEquals(false, $value->getFrontchannelLogoutSessionRequiredOrDefault(TrustedClientFrontchannelLogoutSessionRequiredVO::from($frontchannelLogoutSessionRequiredOtherValue))->value());
        $this->assertNotEquals(true, $value->getFrontchannelLogoutSessionRequiredOrDefault(TrustedClientFrontchannelLogoutSessionRequiredVO::from($frontchannelLogoutSessionRequiredOtherValue))->value());
        $enabledOneValue = true;
        $enabledOtherValue = false;
        $copy = $value->enabled($enabledOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isEnabled());
        $this->assertNotEquals(false, $value->isEnabled());
        $this->assertEquals(true, $value->getEnabledOrDefault(TrustedClientEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(false, $value->getEnabledOrDefault(TrustedClientEnabledVO::from($enabledOtherValue))->value());
        $value->unsetEnabled();
        $this->assertEquals(false, $value->getEnabledOrDefault(TrustedClientEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(true, $value->getEnabledOrDefault(TrustedClientEnabledVO::from($enabledOtherValue))->value());
        $allowedRedirectsOneValue = new TrustedClientAllowedRedirectsListRef(new TrustedClientAllowedRedirectsItem(
            TrustedClientAllowedRedirectsUidVO::from('one'),
            TrustedClientAllowedRedirectsUrlVO::from('one'),
            TrustedClientAllowedRedirectsVersionVO::from(1)
        ));
        $allowedRedirectsOtherValue = new TrustedClientAllowedRedirectsListRef(new TrustedClientAllowedRedirectsItem(
            TrustedClientAllowedRedirectsUidVO::from('other'),
            TrustedClientAllowedRedirectsUrlVO::from('other'),
            TrustedClientAllowedRedirectsVersionVO::from(2)
        ));
        $copy = $value->allowedRedirects($allowedRedirectsOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TrustedClientAllowedRedirectsListRef(new TrustedClientAllowedRedirectsItem(
            TrustedClientAllowedRedirectsUidVO::from('one'),
            TrustedClientAllowedRedirectsUrlVO::from('one'),
            TrustedClientAllowedRedirectsVersionVO::from(1)
        )), $value->getAllowedRedirects());
        $this->assertNotEquals(new TrustedClientAllowedRedirectsListRef(new TrustedClientAllowedRedirectsItem(
            TrustedClientAllowedRedirectsUidVO::from('other'),
            TrustedClientAllowedRedirectsUrlVO::from('other'),
            TrustedClientAllowedRedirectsVersionVO::from(2)
        )), $value->getAllowedRedirects());
        $this->assertEquals(new TrustedClientAllowedRedirectsListRef(new TrustedClientAllowedRedirectsItem(
            TrustedClientAllowedRedirectsUidVO::from('one'),
            TrustedClientAllowedRedirectsUrlVO::from('one'),
            TrustedClientAllowedRedirectsVersionVO::from(1)
        )), $value->getAllowedRedirectsOrDefault(TrustedClientAllowedRedirectsVO::from($allowedRedirectsOtherValue))->value());
        $this->assertNotEquals(new TrustedClientAllowedRedirectsListRef(new TrustedClientAllowedRedirectsItem(
            TrustedClientAllowedRedirectsUidVO::from('other'),
            TrustedClientAllowedRedirectsUrlVO::from('other'),
            TrustedClientAllowedRedirectsVersionVO::from(2)
